# Compléments du lot FRENCH_CANADIAN_USA / FUR_TRADE_USA (novembre 2026) : passages non encore exploités de quatre ouvrages et d'une chronologie (dossier GERVAIS_NOLAN)
# du Drive de l'auteur. Corpus « Recherches », préfixe LUS.
#   Mackie, Richard Somerset (1997), Trading Beyond the Mountains: The British Fur Trade on the Pacific, 1793-1843, Vancouver, UBC Press.
#   Vermette, David (2018), A Distinct Alien Race: The Untold Story of Franco-Americans, Montréal, Baraka Books.
#   Luttig, John C. (1920), Journal of a Fur-Trading Expedition on the Upper Missouri, 1812-1813.
#   Kennedy, Jocelyn (1962), Why Illinois Was French, National Society of the Colonial Dames of America in the State of Illinois.
from commun import Corpus
MK = "Mackie, Richard Somerset (1997), Trading Beyond the Mountains: The British Fur Trade on the Pacific, 1793-1843, Vancouver, UBC Press"
VE = "Vermette, David (2018), A Distinct Alien Race: The Untold Story of Franco-Americans, Montréal, Baraka Books"
KE = "Kennedy, Jocelyn (1962), Why Illinois Was French, The National Society of the Colonial Dames of America in the State of Illinois"
C = Corpus('Recherches', 'LUS', MK, page_fmt='p. {}')
F = C.F
F('01', "La Jolie Prairie : le site du fort Vancouver choisi par Simpson (1824-1825)", 'toponymie', '1824/1825', -122.6620, 45.6260, 'c', ['George Simpson', 'John McLoughlin', 'Alexander Mackenzie'],
  "À quelque quatre-vingt-seize milles en amont du fort George, à l'endroit où le lieutenant Broughton avait arrêté son relevé de la Columbia, les traiteurs connaissaient déjà le lieu sous le nom de Jolie Prairie, sur les pentes qui montent de la pointe Bellevue. Simpson y voit un site admirable pour une ferme capable de produire tout le blé nécessaire au commerce côtier, et pense pouvoir y détacher trente-cinq des soixante-dix hommes du fort George : c'est là que s'élève le fort Vancouver en 1825.", '73', "Voir aussi Foxcurran et al., Songs Upon the Rivers (2016), p. 70.")
F('02', "Portage des brigades : Poulet Paul, de la brigade de la Saskatchewan, porte six pièces (504 livres) sur un mille", 'personnage', '1825~/1843~', -117.0, 52.0, 'h', ['Poulet Paul'],
  "Aux portages des brigades, chaque voyageur devait porter de huit à dix pièces sur un mille par jour, par étapes d'un quart de mille, deux pièces à la fois. Certains étaient d'une force remarquable : Poulet Paul, de la brigade de la Saskatchewan, porta six pièces, soit 504 livres, sur un mille sans se reposer.", '51', "Point indicatif sur la route des brigades entre la Saskatchewan et la Columbia.")
F('03', "Saint-Paul (Prairie française, Oregon) : Hyacinthe Lavigueur, parti de Montréal dans les années 1820", 'migration', '1820~/1840~', -122.9760, 45.2110, 'a', ['Hyacinthe Lavigueur'],
  "David Vermette évoque le frère de son ancêtre, Hyacinthe Lavigueur, qui quitte l'île de Montréal dans les années 1820, très probablement au service de la Compagnie de la Baie d'Hudson, et contribue à fonder la paroisse de Saint-Paul, dans la région de l'Oregon encore appelée French Prairie. Vermette retrouve aussi des Lavigueur parmi les familles canadiennes de Brunswick (Maine), reliées par la parenté à Roxton Falls.", '96', source=VE)
F('04', "Kaskaskia : les sobriquets de voyageurs, « La Tulippe », « Le Violet » et le notaire Billeron « La Fatigue »", 'personne', '1720~/1763', -89.9150, 37.9214, 'h', ['La Tulippe', 'Le Violet', 'Léonard Billeron'],
  "Le coureur de bois portait un nom de famille que personne ne connaissait, un prénom et un « dit » ; seul le sobriquet restait. « La Tulippe » et « Le Violet », noms d'hommes qui se rasaient rarement, figurent dans les contrats des marchands de Montréal et sur les rôles de recensement de Kaskaskia. Les villageois avaient aussi les leurs : le notaire royal Léonard Billeron était appelé « La Fatigue ».", '13-14', source=KE)
LU = "Luttig, John C. (1920), Journal of a Fur-Trading Expedition on the Upper Missouri, 1812-1813, éd. Stella M. Drumm, St. Louis, Missouri Historical Society"
F('05', "Sous l'embouchure de la Platte : le voyageur Baptiste Latulippe se noie (26 juin 1812)", 'evenement', '1812-06-26', -95.880, 41.040, 'a', ['Jean-Baptiste Latulippe', 'Manuel Lisa', 'John C. Luttig'],
  "Le 26 juin 1812, vers sept heures du matin, deux jours après la Saint-Jean, Baptiste Latulippe, de Saint-Louis, tombe par-dessus bord d'un des bateaux de Lisa remontant le Missouri et disparaît, sans doute pris sous les racines d'un gros arbre qu'il allait pousser de sa perche ; l'expédition atteint la Platte vers onze heures. Selon l'éditrice, il s'était engagé en 1805 auprès de Louis-Aimable Desmarais pour chasser le castor et avait servi en 1806 Auguste Chouteau sur l'Osage, où Pike l'employa comme messager le 14 août ; un José Latulippe, tailleur de pierre, figure au recensement de Sainte-Geneviève de 1787 pour le fort Céleste de New Madrid.", '42-43', "Point placé juste en aval de l'embouchure de la Platte.", source=LU)
GN = "Chronologie de la concession Gervacio Nolan (image numérisée, dossier GERVAIS_NOLAN du Drive de l'auteur, source imprimée non identifiée)"
F('06', "Concession Nolan du Nouveau-Mexique : d'Armijo (1845) à Pinkerton c. Ledoux (1888) et au rejet de 1892", 'etablissement', '1845/1892', -104.750, 35.950, 'a', ['Gervais Nolan', 'Juan Antonio Aragón', 'Antonio María Lucero', 'Manuel Armijo', 'Tomás Benito Lalande', 'William Pinkerton', 'Ledoux', 'Maria Dolores Lalande'],
  "Venu du Canada en 1824, Gervais (Gervacio) Nolan épouse en 1828 Maria Dolores Lalande, fille de Jean-Baptiste Lalande et de Maria Rita Abeyta, est naturalisé mexicain en 1829, trappe en 1830-1831, tient en 1835 un magasin et une forge au Real del Oro et réside en 1846 à San Francisco del Tuerto. En 1845, avec Juan Antonio Aragón et Antonio María Lucero, il obtient du gouverneur Manuel Armijo une concession dont son beau-frère Tomás Benito Lalande lui donne possession ; de 1853 à 1857, lui et son fils Francisco y cherchent des colons. Après sa mort (1857), ses héritiers vendent en 1875 la moitié ouest à l'éleveur écossais William Pinkerton pour 40 000 $ ; l'arpentage Shaw (1881-1882) y compte plus de 575 000 acres, la Cour suprême déboute en 1888 Pinkerton contre le colon Ledoux (Pinkerton v. Ledoux), et la Cour des réclamations foncières privées rejette la demande en 1892.", '', "Distincte de la concession Nolan du Colorado (« Cuerno Verde », C123). Emplacement approximatif près de Wagon Mound.", source=GN)
fiches = C.fiches
